package cli

// retiredDenyRuleSessionStartWarning is the SessionStart notice for a repo whose
// agent permission config still carries the retired metadata deny rule.
//
// It reports and points at the fix; it does not repair. See the call site in
// handleLifecycleSessionStart for why nothing on the hook path writes that file:
// it is normally tracked in git, so a silent edit would dirty the worktree and
// could be swept into the user's next checkpoint commit.
//
// Deliberately short. It shares the session-start banner with the agent-help
// pointer and any concurrent-session count, and a wall of text there is its own
// problem — the user needs to know the prompts have a cause and that one command
// clears it.
func retiredDenyRuleSessionStartWarning() string {
	return "\n  A retired Entire permission rule in this repo is causing repeated" +
		"\n  approval prompts. Run 'entire doctor' to remove it."
}

